<AppHead title="Notifikasi" /><div class="mx-auto flex w-full max-w-3xl flex-col gap-6 px-4 py-6 sm:px-6 lg:px-8"><header class="flex flex-col gap-4 border-b pb-5 sm:flex-row sm:items-end sm:justify-between"><div><h1 class="text-2xl font-semibold tracking-tight">Notifikasi</h1><p class="mt-1 text-sm text-muted-foreground">{unreadCount > 0 ? `${unreadCount} notifikasi belum dibaca.` : 'Semua notifikasi sudah dibaca.'}</p></div>{#if unreadCount > 0}<Link href={toUrl(NotificationController.readAll())} method="post" as="button" class="inline-flex min-h-10 items-center rounded-md border px-3 text-sm hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring">Tandai semua dibaca</Link>{/if}</header><nav class="flex gap-2" aria-label="Filter notifikasi"><Link href={toUrl(notificationsIndex())} aria-current={!unread ? 'page' : undefined} class="rounded-md border px-3 py-2 text-sm hover:bg-muted { !unread ? 'bg-muted font-medium' : 'text-muted-foreground' }">Semua</Link><Link href={toUrl(notificationsIndex({ query: { unread: 1 } }))} aria-current={unread ? 'page' : undefined} class="rounded-md border px-3 py-2 text-sm hover:bg-muted { unread ? 'bg-muted font-medium' : 'text-muted-foreground' }">Belum dibaca{#if unreadCount > 0}<Badge variant="secondary" class="ml-2">{unreadCount}</Badge>{/if}</Link></nav>{#if notifications.length === 0}<div class="rounded-lg border border-dashed px-6 py-12 text-center text-sm text-muted-foreground">{unread ? 'Tidak ada notifikasi belum dibaca.' : 'Belum ada notifikasi.'}</div>{:else}<div class="divide-y rounded-lg border bg-card">{#each notifications as notification (notification.id)}<div class="flex items-start justify-between gap-4 px-4 py-4 {notification.read_at ? '' : 'bg-muted/30'}"><Link href={notification.url} class="min-w-0 flex-1"><div class="flex items-center gap-2"><h2 class="text-sm font-semibold">{notification.title}</h2>{#if !notification.read_at}<Badge variant="secondary">Baru</Badge>{/if}</div><p class="mt-1 text-sm text-muted-foreground">{notification.message}</p><p class="mt-2 text-xs text-muted-foreground">{notification.created_at ?? ''}</p></Link>{#if !notification.read_at}<Link href={toUrl(NotificationController.read({ notification: notification.id }))} method="post" as="button" class="text-xs text-muted-foreground hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring">Tandai dibaca</Link>{/if}</div>{/each}</div>{/if}</div>
